do $post017$
declare
  v_rest integer; v_places integer; v_unver integer; v_coords integer;
  v_nolink integer; v_nosrc integer; v_type integer;
begin
  select count(*) into v_rest from public.restaurants where source = 'tptm-b17';
  if v_rest <> 53 then
    raise exception 'POSTFLIGHT FAIL: expected 53 batch-017 restaurant rows, found %.', v_rest;
  end if;
  select count(*) into v_places from public.places where source = 'tptm-b17';
  if v_places <> 29 then
    raise exception 'POSTFLIGHT FAIL: expected 29 batch-017 place rows, found %.', v_places;
  end if;

  select count(*) into v_unver from public.restaurants where source = 'tptm-b17' and verification_status <> 'unverified';
  v_unver := v_unver + (select count(*) from public.places where source = 'tptm-b17' and verification_status <> 'unverified');
  if v_unver <> 0 then
    raise exception 'POSTFLIGHT FAIL: % rows are not unverified — an import never self-verifies.', v_unver;
  end if;

  select count(*) into v_coords from public.restaurants where source = 'tptm-b17' and (latitude is not null or longitude is not null);
  v_coords := v_coords + (select count(*) from public.places where source = 'tptm-b17' and latitude is not null);
  if v_coords <> 0 then
    raise exception 'POSTFLIGHT FAIL: expected ZERO coordinate rows (published OSM coords stay in evidence), found %.', v_coords;
  end if;

  select count(*) into v_nolink from public.places where source = 'tptm-b17' and destination_id is null;
  if v_nolink <> 0 then
    raise exception 'POSTFLIGHT FAIL: % place rows missing destination linkage.', v_nolink;
  end if;

  select count(*) into v_nosrc from public.restaurants where source = 'tptm-b17' and (source_url is null or source_url = '');
  v_nosrc := v_nosrc + (select count(*) from public.places where source = 'tptm-b17' and (source_url is null or source_url = ''));
  if v_nosrc <> 0 then
    raise exception 'POSTFLIGHT FAIL: % rows missing source_url.', v_nosrc;
  end if;
  select count(*) filter (where place_type = 'temple') into v_type from public.places where source = 'tptm-b17';
  if v_type <> 9 then
    raise exception 'POSTFLIGHT FAIL: place_type temple drifted (found %; expected 9).', v_type;
  end if;
  select count(*) filter (where place_type = 'other') into v_type from public.places where source = 'tptm-b17';
  if v_type <> 17 then
    raise exception 'POSTFLIGHT FAIL: place_type other drifted (found %; expected 17).', v_type;
  end if;
  select count(*) filter (where place_type = 'waterfall') into v_type from public.places where source = 'tptm-b17';
  if v_type <> 1 then
    raise exception 'POSTFLIGHT FAIL: place_type waterfall drifted (found %; expected 1).', v_type;
  end if;
  select count(*) filter (where place_type = 'hotel') into v_type from public.places where source = 'tptm-b17';
  if v_type <> 2 then
